import{_ as t,o as n,c as r,a3 as i}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse('{"title":"MQTT-Client","description":"Ausgewählte Home-Assistant-Werte live per MQTT übertragen und gezielt steuern.","frontmatter":{"title":"MQTT-Client","description":"Ausgewählte Home-Assistant-Werte live per MQTT übertragen und gezielt steuern."},"headers":[],"relativePath":"projects/mqtt-client/index.md","filePath":"projects/mqtt-client/index.md","lastUpdated":1792840662000}'),a={name:"projects/mqtt-client/index.md"};function d(s,e,l,o,u,c){return n(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="mqtt-client-0-1-16" tabindex="-1">MQTT-Client 0.1.16 <a class="header-anchor" href="#mqtt-client-0-1-16" aria-label="Permalink to &quot;MQTT-Client 0.1.16&quot;">​</a></h1><p>MQTT-Client überträgt ausgewählte Geräte, Zustände und Attribute aus Home Assistant an einen externen MQTT-Broker, beispielsweise den MQTT-Adapter von ioBroker. Statt sämtliche HA-Entitäten zu spiegeln, wählst du die benötigten Werte selbst aus. Der vorhandene HA-Broker bleibt bestehen. Die App liest direkt aus HA; sie ist keine Broker-Bridge.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/mqtt_client" target="_blank" rel="noreferrer">Quellcode und Konfigurationsreferenz</a> · <a href="/en/projects/mqtt-client/">English documentation</a></p><h2 id="einrichtung-und-auswahl" tabindex="-1">Einrichtung und Auswahl <a class="header-anchor" href="#einrichtung-und-auswahl" aria-label="Permalink to &quot;Einrichtung und Auswahl&quot;">​</a></h2><ol><li><code>https://github.com/rockbaer2007/ugso-ha-mqtt-addons</code> im Home-Assistant-App-Store hinzufügen.</li><li><strong>MQTT-Client</strong> installieren und starten; unterstützt werden amd64 und aarch64.</li><li>Die Weboberfläche öffnen und Host, Port, Benutzer und Passwort des externen Brokers speichern. Ohne TLS ist der Standardport 1883.</li><li>Links ein Gerät auswählen. Im Dialog sind seine Entitäten nach Steuerung, Sensoren, Konfiguration und Diagnose gruppiert. Die Suche findet auch Entitäten innerhalb eines Geräts.</li><li>Die gewünschten Werte und Attribute auswählen. Das Kontrollkästchen rechts in einer Wertzeile überträgt den Zustand einschließlich aller Attribute; die Geräteauswahl kann sämtliche Werte des Geräts übernehmen.</li></ol><p>Änderungen werden unmittelbar übernommen. Ein zusätzlicher HA-Zugriffstoken ist nicht nötig: Die App verwendet den Supervisor-Zugang zur HA-Core-API. Für mehrere Instanzen unterschiedliche Client-IDs und Themenpräfixe verwenden.</p><h2 id="live-ubertragung-und-status" tabindex="-1">Live-Übertragung und Status <a class="header-anchor" href="#live-ubertragung-und-status" aria-label="Permalink to &quot;Live-Übertragung und Status&quot;">​</a></h2><p>Nach dem vollständigen Anfangsstand verarbeitet die App HA-Zustandsänderungen live über WebSocket. Nach einer erneuten HA-Verbindung wird der Anfangsstand neu eingelesen; nach einer MQTT-Neuverbindung werden alle ausgewählten Werte erneut übertragen.</p><p>Bei ausgefallener Live-Verbindung bleibt die bisherige Abfrage als Fallback aktiv: <strong>standardmäßig alle fünf Sekunden</strong>, einstellbar über <code>poll_interval</code> von 1 bis 300 Sekunden. Während einer Unterbrechung oder zwischen Fallback-Abfragen verpasste Änderungen lassen sich nicht nachträglich rekonstruieren. Eine überlastete Ereigniswarteschlange wird angezeigt und löst eine erneute Synchronisierung aus.</p><p>Der Status unterscheidet MQTT-Verbindung und HA-Erreichbarkeit und zeigt Live-/Abfragemodus, letzte Synchronisierung, letzte Veröffentlichung, Anzahl der Veröffentlichungen und bereinigte Fehlertypen. Zugangsdaten und Nachrichteninhalte werden dort nicht ausgegeben.</p><table tabindex="0"><thead><tr><th>MQTT-Thema</th><th>Inhalt</th></tr></thead><tbody><tr><td><code>&lt;topic_prefix&gt;/&lt;device&gt;/&lt;value&gt;/state</code></td><td>Zustand als Text</td></tr><tr><td><code>&lt;topic_prefix&gt;/&lt;device&gt;/&lt;value&gt;/attribute/&lt;attribute&gt;</code></td><td>Ausgewähltes Attribut</td></tr><tr><td><code>&lt;topic_prefix&gt;/&lt;device&gt;/&lt;value&gt;/set</code></td><td>Rückkanal für unterstützte Steuerbefehle</td></tr><tr><td><code>&lt;topic_prefix&gt;/availability</code></td><td><code>online</code> nach erfolgreicher HA-Synchronisierung, sonst <code>offline</code></td></tr></tbody></table><p>Standardpräfix ist <code>ha_external</code>. Zustände und Attribute werden mit QoS 1 und Retain veröffentlicht; MQTT-Discovery wird nicht erzeugt. Beim ersten Aufbau kommen Zustände und Attribute vor den <code>/set</code>-Rückkanälen, standardmäßig mit 50 ms Abstand zwischen Veröffentlichungen. <code>unknown</code> und <code>unavailable</code> werden weitergereicht; fehlende Entitäten liefern <code>unavailable</code>.</p><h2 id="steuerbefehle-zuruck-an-ha" tabindex="-1">Steuerbefehle zurück an HA <a class="header-anchor" href="#steuerbefehle-zuruck-an-ha" aria-label="Permalink to &quot;Steuerbefehle zurück an HA&quot;">​</a></h2><p>Für ausgewählte steuerbare Entitäten werden Rückkanäle automatisch aktiviert. Sensoren bleiben reine Ausgänge. Befehle an das passende <code>/set</code>-Thema <strong>ohne Retain</strong> senden.</p><table tabindex="0"><thead><tr><th>Entität</th><th>Nutzdaten</th></tr></thead><tbody><tr><td>Schaltbare Entität</td><td><code>ON</code> oder <code>OFF</code></td></tr><tr><td><code>number</code>, <code>input_number</code></td><td>Zahlenwert</td></tr><tr><td><code>select</code>, <code>input_select</code></td><td>Name einer verfügbaren Option</td></tr><tr><td><code>text</code>, <code>input_text</code></td><td>Text</td></tr><tr><td><code>button</code>, <code>input_button</code></td><td><code>PRESS</code></td></tr><tr><td><code>cover</code></td><td><code>OPEN</code>, <code>CLOSE</code>, <code>STOP</code> oder <code>{&quot;position&quot;:45}</code></td></tr><tr><td><code>light</code></td><td><code>{&quot;brightness_pct&quot;:75}</code></td></tr><tr><td><code>fan</code></td><td><code>{&quot;percentage&quot;:50}</code></td></tr></tbody></table><p>Die JSON-Befehle erlauben jeweils nur das genannte Feld und eine endliche Zahl von 0 bis 100. Das HA-Gerät muss die Funktion unterstützen. Alte Entitäts-ID-Themen wie <code>ha_external/switch.plug/set</code> bleiben gültig. Retained-Befehle, veraltete Befehle und ungültige Inhalte werden verworfen; beliebige HA-Aktionsaufrufe sind nicht vorgesehen.</p><h2 id="veraltete-retain-topics-entfernen" tabindex="-1">Veraltete Retain-Topics entfernen <a class="header-anchor" href="#veraltete-retain-topics-entfernen" aria-label="Permalink to &quot;Veraltete Retain-Topics entfernen&quot;">​</a></h2><p><strong>Veraltete Retain-Topics prüfen</strong> zeigt aufgezeichnete Themen, die durch geänderte Auswahl, Präfixe oder Gerätenamen nicht mehr verwendet werden. Gewünschte Themen markieren und das Löschen bestätigen; höchstens 100 pro Vorgang.</p><p>Die App löscht ausschließlich eigene, erfolgreich bestätigte Veröffentlichungen auf dem aktuell konfigurierten Broker. Aktive und fremde Themen bleiben geschützt. Das Inventar liegt dauerhaft in <code>/data/mqtt-topics.json</code>. Fehlgeschlagene Löschungen bleiben für einen erneuten Versuch erhalten. Es gibt <strong>keine automatische Bereinigung</strong>. Nicht aufgezeichnete Alt-Themen aus der Zeit vor diesem Update müssen weiterhin direkt am Broker entfernt werden.</p><h2 id="einstellungen-sichern-und-wiederherstellen" tabindex="-1">Einstellungen sichern und wiederherstellen <a class="header-anchor" href="#einstellungen-sichern-und-wiederherstellen" aria-label="Permalink to &quot;Einstellungen sichern und wiederherstellen&quot;">​</a></h2><p><strong>Einstellungen sichern</strong> lädt eine JSON-Datei mit Broker-Einstellungen, Client-ID, Themenpräfix, Auswahl, Abfrageintervall, Veröffentlichungsabstand und eigener CA herunter. <strong>Sicherung öffnen</strong> prüft die Datei und fragt vor dem Ersetzen nach.</p><p>Die Datei enthält <strong>kein MQTT-Passwort, kein Client-Zertifikat, keinen privaten Schlüssel und keinen HA-Token</strong>. Sie ist nicht verschlüsselt. Bei gleichem Broker bleiben lokal gespeicherte Zugangsdaten und Client-Zertifikat/Schlüssel erhalten. Bei einem anderen Broker müssen diese neu eingegeben werden. Retained-Inhalte sind nicht enthalten; eine vollständige HA-App-Sicherung wird dadurch nicht ersetzt.</p><h2 id="tls-mit-eigenen-zertifikaten" tabindex="-1">TLS mit eigenen Zertifikaten <a class="header-anchor" href="#tls-mit-eigenen-zertifikaten" aria-label="Permalink to &quot;TLS mit eigenen Zertifikaten&quot;">​</a></h2><p>Unter <strong>Übertragung und TLS</strong> können eigene CA, Client-Zertifikat und privater Schlüssel als PEM-Dateien geladen oder als Text eingefügt werden. Zertifikat und Schlüssel müssen zusammen vorliegen. Der TLS-Port richtet sich nach dem Broker, häufig 8883.</p><p>Serverzertifikat und Hostname werden immer geprüft, mit Systemvertrauen oder eigener CA. Leere Geheimnisfelder behalten gespeicherte Werte. Zum Entfernen die ausdrückliche Option <strong>Gespeicherte TLS-Zertifikate und Schlüssel entfernen</strong> aktivieren und speichern. Ungültige TLS-Konfigurationen werden vor dem Ändern der Einstellungen abgewiesen.</p><h2 id="update-und-kompatibilitat" tabindex="-1">Update und Kompatibilität <a class="header-anchor" href="#update-und-kompatibilitat" aria-label="Permalink to &quot;Update und Kompatibilität&quot;">​</a></h2><p>Bestehende Einstellungen aus 0.1.15 bleiben gültig: Broker-Zugangsdaten, Geräte-/Attributauswahl, Client-ID, Themenpräfix, Abfrageintervall und Veröffentlichungsabstand werden beim Start nicht umgeschrieben. TLS bleibt in seiner bisherigen Einstellung; neue Zertifikatsfelder sind standardmäßig leer. Retained-Daten werden beim Update nicht gelöscht.</p><p>Version 0.1.16 wurde mit Backend-Tests, einem MQTT-Broker, einer WebSocket-Gegenstelle, TLS mit Client-Zertifikat, Weboberfläche und Docker-Start geprüft. Die tatsächliche HA-Installation und die unterstützten Gerätefunktionen müssen mit der eigenen Umgebung geprüft werden.</p>',28)])])}const b=t(a,[["render",d]]);export{g as __pageData,b as default};
